280	    /**
281	     * Return the Pet with the given name, or null if none found for this Owner.
282	     *
283	     * @param name to test
284	     * @return true if pet name is already in use
285	     */
286	    public Pet getPet(String name) {
287	        return getPet(name, false);
288	    }
289	
290	    /**
291	     * Return the Pet with the given name, or null if none found for this Owner.
292	     *
293	     * @param name to test
294	     * @return true if pet name is already in use
295	     */
296	    public Pet getPet(String name, boolean ignoreNew) {
297	        name = name.toLowerCase();
298	        for (Pet pet : getPetsInternal()) {
299	            if (!ignoreNew || !pet.isNew()) {
300	                String compName = pet.getName();
301	                compName = compName.toLowerCase();
302	                if (compName.equals(name)) {
303	                    return pet;
304	                }
305	            }
306	        }
307	        return null;
308	    }
309	
310	    public Pet getPet(Integer petId) {
311	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
312	    }
313	
314	    @Override
315	    public String toString() {
316	        return new ToStringCreator(this)
317	
318	            .append("id", this.getId())
319	            .append("new", this.isNew())
320	            .append("lastName", this.getLastName())
321	            .append("firstName", this.getFirstName())
322	            .append("address", this.address)
323	            .append("city", this.city)
324	            .append("telephone", this.telephone)
325	            .append("email", this.email)
326	            .toString();
327	    }
