363	    /**
364	     * The fixed public holidays the business-day roll skips. A registration date landing on any of
365	     * these dates is rolled forward, just as it is for a weekend.
366	     */
367	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
368	        java.time.LocalDate.parse("2026-01-01"),
369	        java.time.LocalDate.parse("2026-01-26"),
370	        java.time.LocalDate.parse("2026-04-25"),
371	        java.time.LocalDate.parse("2026-12-25"),
372	        java.time.LocalDate.parse("2026-12-28"));
