374	    /**
375	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
376	     * holiday is moved forward to the next non-holiday weekday; an ordinary weekday is returned
377	     * unchanged. This applies to the effective registration date whether it was supplied in the
378	     * request or defaulted to the server date, and every value derived from the registration date
379	     * uses the adjusted result.
380	     *
381	     * @param date the effective registration date
382	     * @return {@code date} itself when it is a non-holiday weekday, otherwise the next business day
383	     */
384	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
385	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
386	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
387	            || PUBLIC_HOLIDAYS.contains(date)) {
388	            date = date.plusDays(1);
389	        }
390	        return date;
391	    }
