448	    /**
449	     * Assigns an owner's {@code memberId} on create, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
450	     * owner's canonical region REGION (derived by preferring the postcode, see
451	     * {@link Localities#region(String, String)} — the same region derivation shared with the
452	     * {@code locality}); the 2-digit fiscal year FY of the registration date (see
453	     * {@link org.springframework.samples.petclinic.util.FiscalYears#fiscalYear(java.time.LocalDate)});
454	     * the first 8 upper-case hex characters HASH8 of the SHA-256 digest of the normalized (E.164)
455	     * telephone concatenated with the last name (the same HASH8 used by the region-and-hash identity);
456	     * and a single Luhn check digit CHK computed over the decimal digits contained in
457	     * {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW263A7F9C2E5'}). The id is derived from the owner's
458	     * own identity fields; it carries no sequence number.
459	     * <p>
460	     * When the computed id collides with an existing owner's {@code memberId}, it is de-duplicated by
461	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g.
462	     * {@code 'NSW263A7F9C2E5-2'}), and the de-duplicated id is returned.
463	     *
464	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
465	     * @param telephone the owner's normalized (E.164) telephone
466	     * @param lastName the owner's last name
467	     * @param registrationDate the owner's business-day-adjusted registration date (supplies FY)
468	     * @return the assigned member id, de-duplicated to be unique among existing owners
469	     */
470	    private String assignMemberId(String region, String telephone, String lastName,
471	            java.time.LocalDate registrationDate) {
472	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
473	        String hash8 = sha256UpperHex(basis).substring(0, 8);
474	        String fy = String.format("%02d",
475	            org.springframework.samples.petclinic.util.FiscalYears.fiscalYear(registrationDate) % 100);
476	        String base = region + fy + hash8;
477	        String memberId = base
478	            + org.springframework.samples.petclinic.util.CheckDigits.luhn(base);
479	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
480	            .map(Owner::getMemberId)
481	            .filter(java.util.Objects::nonNull)
482	            .collect(java.util.stream.Collectors.toSet());
483	        if (!existing.contains(memberId)) {
484	            return memberId;
485	        }
486	        for (int n = 2; ; n++) {
487	            String candidate = memberId + "-" + n;
488	            if (!existing.contains(candidate)) {
489	                return candidate;
490	            }
491	        }
492	    }
