494	    /**
495	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
496	     */
497	    private static String sha256UpperHex(String value) {
498	        try {
499	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
500	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
501	            StringBuilder sb = new StringBuilder(digest.length * 2);
502	            for (byte b : digest) {
503	                sb.append(String.format("%02X", b));
504	            }
505	            return sb.toString();
506	        }
507	        catch (java.security.NoSuchAlgorithmException e) {
508	            throw new IllegalStateException("SHA-256 not available", e);
509	        }
510	    }
