549	    /**
550	     * Computes the {@code membershipLevel} to store for the owner being created, applying the household
551	     * ceiling. The owner's natural level is first derived from their own fields (see
552	     * {@link org.springframework.samples.petclinic.util.Memberships#membershipLevel(String, Integer, Integer, java.time.LocalDate)}).
553	     * It is then capped so it cannot exceed one above the current maximum {@code membershipLevel} among
554	     * the owner's existing household members (the non-deleted owners sharing its {@code householdId}, see
555	     * {@link Households#householdId}). When the owner has no existing household member no cap applies and
556	     * the natural level is returned.
557	     *
558	     * @param owner the owner being created, with its level-affecting fields already populated
559	     * @return the (possibly capped) membership level to store on the owner
560	     */
561	    private int cappedMembershipLevel(Owner owner) {
562	        int naturalLevel = org.springframework.samples.petclinic.util.Memberships.membershipLevel(
563	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
564	        String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
565	        Integer householdSize = owner.getHouseholdSize();
566	        java.util.OptionalInt maxMemberLevel = this.clinicService.findAllOwners().stream()
567	            .filter(this::isNotDeleted)
568	            .filter(existing -> householdId.equals(
569	                Households.householdId(existing.getLastName(), existing.getPostcode())))
570	            .mapToInt(existing -> effectiveMembershipLevel(existing, householdSize))
571	            .max();
572	        if (maxMemberLevel.isEmpty()) {
573	            return naturalLevel;
574	        }
575	        return Math.min(naturalLevel, maxMemberLevel.getAsInt() + 1);
576	    }
