578	    /**
579	     * Returns an existing household member's effective {@code membershipLevel} for the purpose of the
580	     * household ceiling, evaluated at the household's {@code currentHouseholdSize} (the size the
581	     * household reaches once the owner being created joins). A member's stored level is a snapshot taken
582	     * when that member was created, when the household may have been smaller and so not yet qualified
583	     * for the household points; as the household grows every member's standing rises with it. The
584	     * effective level is therefore the greater of the member's stored level (when present) and the level
585	     * recomputed from the member's own fields at the current household size, so a household that has
586	     * grown large enough to earn the household points lifts the ceiling for later joiners rather than
587	     * pinning them to a stale, pre-growth snapshot.
588	     *
589	     * @param owner an existing household member
590	     * @param currentHouseholdSize the household size after the owner being created joins
591	     * @return the member's effective membership level at the current household size
592	     */
593	    private int effectiveMembershipLevel(Owner owner, Integer currentHouseholdSize) {
594	        int recomputed = org.springframework.samples.petclinic.util.Memberships.membershipLevel(
595	            owner.getEmail(), owner.getNamesakeCount(), currentHouseholdSize, owner.getRegistrationDate());
596	        if (owner.getMembershipLevel() != null) {
597	            return Math.max(owner.getMembershipLevel(), recomputed);
598	        }
599	        return recomputed;
600	    }
