602	    /**
603	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
604	     * sharing this owner's {@code soundex(lastName)} and postcode (an exact match of the stored 4-digit
605	     * value) while carrying a <em>different</em> {@code identityKey}. A soft match is distinct from the
606	     * hard duplicate rejected earlier by {@link #rejectDuplicateIdentity} (which requires an identical
607	     * identity key): the owner is still created, but flagged. Because the telephone is part of the
608	     * identity key, two owners with the same last name and postcode but different telephones are a soft
609	     * match rather than a hard duplicate. When more than one existing owner matches, the earliest
610	     * (lowest id) is returned so the reference is deterministic. An owner with no postcode can never
611	     * soft-match.
612	     *
613	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
614	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
615	     */
616	    private Integer findPossibleDuplicateOf(Owner owner) {
617	        String postcode = owner.getPostcode();
618	        if (postcode == null) {
619	            return null;
620	        }
621	        String soundex = Households.soundex(owner.getLastName());
622	        String identity = Households.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
623	        return this.clinicService.findAllOwners().stream()
624	            .filter(this::isNotDeleted)
625	            .filter(existing -> soundex.equals(Households.soundex(existing.getLastName())))
626	            .filter(existing -> postcode.equals(existing.getPostcode()))
627	            .filter(existing -> !identity.equals(Households.identityKey(
628	                toE164OrNull(existing.getTelephone()), existing.getEmail(), existing.getLastName())))
629	            .map(Owner::getId)
630	            .filter(java.util.Objects::nonNull)
631	            .min(java.util.Comparator.naturalOrder())
632	            .orElse(null);
633	    }
