635	    /**
636	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
637	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
638	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
639	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
640	     * {@code "+61412345678"}. The E.164 value is stored and returned.
641	     * <p>
642	     * The national-number length (the digits after the country code) is additionally validated for
643	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
644	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
645	     *
646	     * @param telephone the raw telephone as submitted
647	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
648	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
649	     *         or its national-number length is wrong for its country code
650	     */
651	    private String normalizeTelephone(String telephone) {
652	        String raw = telephone == null ? "" : telephone.trim();
653	        boolean hasCountryCode = raw.startsWith("+");
654	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
655	        if (hasCountryCode) {
656	            cleaned = cleaned.substring(1);
657	        }
658	        String digits;
659	        if (hasCountryCode) {
660	            digits = cleaned;
661	        } else {
662	            if (cleaned.startsWith("0")) {
663	                cleaned = cleaned.substring(1);
664	            }
665	            digits = "61" + cleaned;
666	        }
667	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
668	            throw new InvalidTelephoneException(telephone);
669	        }
670	        return "+" + digits;
671	    }
672	
673	    /**
674	     * Checks the national-number length of an E.164 digit string against its country code for the
675	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
676	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
677	     *
678	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
679	     * @return {@code true} if the national-number length is acceptable for the country code
680	     */
681	    private boolean hasValidNationalLength(String digits) {
682	        if (digits.startsWith("61")) {
683	            return digits.length() - 2 == 9;
684	        }
685	        if (digits.startsWith("1")) {
686	            return digits.length() - 1 == 10;
687	        }
688	        return true;
689	    }
