691	    /**
692	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
693	     * multi-character top-level label. Deliberately lenient about the exact character set while still
694	     * rejecting values that are clearly not addresses (e.g. missing '@').
695	     */
696	    private static final java.util.regex.Pattern EMAIL_PATTERN =
697	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
698	
699	    /**
700	     * Domains of known disposable/throwaway email providers. An owner whose email domain is on this
701	     * blocklist is rejected with a 400 Bad Request. Compared case-insensitively against the
702	     * lower-cased email domain.
703	     */
704	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
705	        "mailinator.com", "tempmail.com", "guerrillamail.com");
706	
707	    /**
708	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
709	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
710	     * lower-cased before being stored and returned.
711	     *
712	     * @param email the raw email as submitted, may be {@code null}
713	     * @return the lower-cased email, or {@code null} when none was supplied
714	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
715	     */
716	    private String normalizeEmail(String email) {
717	        if (email == null || email.isBlank()) {
718	            return null;
719	        }
720	        String trimmed = email.trim();
721	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
722	            throw new InvalidEmailException(email);
723	        }
724	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
725	        String domain = normalized.substring(normalized.indexOf('@') + 1);
726	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
727	            throw new DisposableEmailException(email);
728	        }
729	        return normalized;
730	    }
